00046 /* MD5 functions */
00047 #define MD5FUNC(f, w, x, y, z, msg1, s, msg2) (w += f(x, y, z) + msg1 + msg2, w = w << s | w >> (32 - s), w += x)
00048 #define FF(x, y, z) (z ^ (x & (y ^ z)))
00049 #define GG(x, y, z) (y ^ (z & (x ^ y)))
00050 #define HH(x, y, z) (x ^ y ^ z)
00051 #define II(x, y, z) (y ^ (x | ~z))
00052 
00054 
00055 static void lcevc_md5_trans(u32 *buf, u32 *msg) {
00056     register u32 a, b, c, d;
00057 
00058     a = buf[0];
00059     b = buf[1];
00060     c = buf[2];
00061     d = buf[3];
00062 
00063     MD5FUNC(FF, a, b, c, d, msg[0], 7, 0xd76aa478);  /* 1 */
00064     MD5FUNC(FF, d, a, b, c, msg[1], 12, 0xe8c7b756); /* 2 */
00065     MD5FUNC(FF, c, d, a, b, msg[2], 17, 0x242070db); /* 3 */
00066     MD5FUNC(FF, b, c, d, a, msg[3], 22, 0xc1bdceee); /* 4 */
00067 
00068     MD5FUNC(FF, a, b, c, d, msg[4], 7, 0xf57c0faf);  /* 5 */
00069     MD5FUNC(FF, d, a, b, c, msg[5], 12, 0x4787c62a); /* 6 */
00070     MD5FUNC(FF, c, d, a, b, msg[6], 17, 0xa8304613); /* 7 */
00071     MD5FUNC(FF, b, c, d, a, msg[7], 22, 0xfd469501); /* 8 */
00072 
00073     MD5FUNC(FF, a, b, c, d, msg[8], 7, 0x698098d8);   /* 9 */
00074     MD5FUNC(FF, d, a, b, c, msg[9], 12, 0x8b44f7af);  /* 10 */
00075     MD5FUNC(FF, c, d, a, b, msg[10], 17, 0xffff5bb1); /* 11 */
00076     MD5FUNC(FF, b, c, d, a, msg[11], 22, 0x895cd7be); /* 12 */
00077 
00078     MD5FUNC(FF, a, b, c, d, msg[12], 7, 0x6b901122);  /* 13 */
00079     MD5FUNC(FF, d, a, b, c, msg[13], 12, 0xfd987193); /* 14 */
00080     MD5FUNC(FF, c, d, a, b, msg[14], 17, 0xa679438e); /* 15 */
00081     MD5FUNC(FF, b, c, d, a, msg[15], 22, 0x49b40821); /* 16 */
00082 
00083     /* Round 2 */
00084     MD5FUNC(GG, a, b, c, d, msg[1], 5, 0xf61e2562);   /* 17 */
00085     MD5FUNC(GG, d, a, b, c, msg[6], 9, 0xc040b340);   /* 18 */
00086     MD5FUNC(GG, c, d, a, b, msg[11], 14, 0x265e5a51); /* 19 */
00087     MD5FUNC(GG, b, c, d, a, msg[0], 20, 0xe9b6c7aa);  /* 20 */
00088 
00089     MD5FUNC(GG, a, b, c, d, msg[5], 5, 0xd62f105d);   /* 21 */
00090     MD5FUNC(GG, d, a, b, c, msg[10], 9, 0x2441453);   /* 22 */
00091     MD5FUNC(GG, c, d, a, b, msg[15], 14, 0xd8a1e681); /* 23 */
00092     MD5FUNC(GG, b, c, d, a, msg[4], 20, 0xe7d3fbc8);  /* 24 */
00093 
00094     MD5FUNC(GG, a, b, c, d, msg[9], 5, 0x21e1cde6);  /* 25 */
00095     MD5FUNC(GG, d, a, b, c, msg[14], 9, 0xc33707d6); /* 26 */
00096     MD5FUNC(GG, c, d, a, b, msg[3], 14, 0xf4d50d87); /* 27 */
00097     MD5FUNC(GG, b, c, d, a, msg[8], 20, 0x455a14ed); /* 28 */
00098 
00099     MD5FUNC(GG, a, b, c, d, msg[13], 5, 0xa9e3e905);  /* 29 */
00100     MD5FUNC(GG, d, a, b, c, msg[2], 9, 0xfcefa3f8);   /* 30 */
00101     MD5FUNC(GG, c, d, a, b, msg[7], 14, 0x676f02d9);  /* 31 */
00102     MD5FUNC(GG, b, c, d, a, msg[12], 20, 0x8d2a4c8a); /* 32 */
00103 
00104     /* Round 3 */
00105     MD5FUNC(HH, a, b, c, d, msg[5], 4, 0xfffa3942);   /* 33 */
00106     MD5FUNC(HH, d, a, b, c, msg[8], 11, 0x8771f681);  /* 34 */
00107     MD5FUNC(HH, c, d, a, b, msg[11], 16, 0x6d9d6122); /* 35 */
00108     MD5FUNC(HH, b, c, d, a, msg[14], 23, 0xfde5380c); /* 36 */
00109 
00110     MD5FUNC(HH, a, b, c, d, msg[1], 4, 0xa4beea44);   /* 37 */
00111     MD5FUNC(HH, d, a, b, c, msg[4], 11, 0x4bdecfa9);  /* 38 */
00112     MD5FUNC(HH, c, d, a, b, msg[7], 16, 0xf6bb4b60);  /* 39 */
00113     MD5FUNC(HH, b, c, d, a, msg[10], 23, 0xbebfbc70); /* 40 */
00114 
00115     MD5FUNC(HH, a, b, c, d, msg[13], 4, 0x289b7ec6); /* 41 */
00116     MD5FUNC(HH, d, a, b, c, msg[0], 11, 0xeaa127fa); /* 42 */
00117     MD5FUNC(HH, c, d, a, b, msg[3], 16, 0xd4ef3085); /* 43 */
00118     MD5FUNC(HH, b, c, d, a, msg[6], 23, 0x4881d05);  /* 44 */
00119 
00120     MD5FUNC(HH, a, b, c, d, msg[9], 4, 0xd9d4d039);   /* 45 */
00121     MD5FUNC(HH, d, a, b, c, msg[12], 11, 0xe6db99e5); /* 46 */
00122     MD5FUNC(HH, c, d, a, b, msg[15], 16, 0x1fa27cf8); /* 47 */
00123     MD5FUNC(HH, b, c, d, a, msg[2], 23, 0xc4ac5665);  /* 48 */
00124 
00125     /* Round 4 */
00126     MD5FUNC(II, a, b, c, d, msg[0], 6, 0xf4292244);   /* 49 */
00127     MD5FUNC(II, d, a, b, c, msg[7], 10, 0x432aff97);  /* 50 */
00128     MD5FUNC(II, c, d, a, b, msg[14], 15, 0xab9423a7); /* 51 */
00129     MD5FUNC(II, b, c, d, a, msg[5], 21, 0xfc93a039);  /* 52 */
00130 
00131     MD5FUNC(II, a, b, c, d, msg[12], 6, 0x655b59c3);  /* 53 */
00132     MD5FUNC(II, d, a, b, c, msg[3], 10, 0x8f0ccc92);  /* 54 */
00133     MD5FUNC(II, c, d, a, b, msg[10], 15, 0xffeff47d); /* 55 */
00134     MD5FUNC(II, b, c, d, a, msg[1], 21, 0x85845dd1);  /* 56 */
00135 
00136     MD5FUNC(II, a, b, c, d, msg[8], 6, 0x6fa87e4f);   /* 57 */
00137     MD5FUNC(II, d, a, b, c, msg[15], 10, 0xfe2ce6e0); /* 58 */
00138     MD5FUNC(II, c, d, a, b, msg[6], 15, 0xa3014314);  /* 59 */
00139     MD5FUNC(II, b, c, d, a, msg[13], 21, 0x4e0811a1); /* 60 */
00140 
00141     MD5FUNC(II, a, b, c, d, msg[4], 6, 0xf7537e82);   /* 61 */
00142     MD5FUNC(II, d, a, b, c, msg[11], 10, 0xbd3af235); /* 62 */
00143     MD5FUNC(II, c, d, a, b, msg[2], 15, 0x2ad7d2bb);  /* 63 */
00144     MD5FUNC(II, b, c, d, a, msg[9], 21, 0xeb86d391);  /* 64 */
00145 
00146     buf[0] += a;
00147     buf[1] += b;
00148     buf[2] += c;
00149     buf[3] += d;
00150 }
00151 
00153 
00154 void lcevc_md5_init(LCEVC_MD5 *md5) {
00155     md5->h[0] = 0x67452301;
00156     md5->h[1] = 0xefcdab89;
00157     md5->h[2] = 0x98badcfe;
00158     md5->h[3] = 0x10325476;
00159 
00160     md5->bits[0] = 0;
00161     md5->bits[1] = 0;
00162 }
00163 
00165 
00166 void lcevc_md5_update(LCEVC_MD5 *md5, void *buf_t, u32 len) {
00167     u8 *buf;
00168     u32 i, idx, part_len;
00169 
00170     buf = (u8 *)buf_t;
00171 
00172     idx = (u32)((md5->bits[0] >> 3) & 0x3f);
00173 
00174     md5->bits[0] += (len << 3);
00175     if (md5->bits[0] < (len << 3)) {
00176         (md5->bits[1])++;
00177     }
00178 
00179     md5->bits[1] += (len >> 29);
00180     part_len = 64 - idx;
00181 
00182     if (len >= part_len) {
00183         lcevc_mcpy(md5->msg + idx, buf, part_len);
00184         lcevc_md5_trans(md5->h, (u32 *)md5->msg);
00185 
00186         for (i = part_len; i + 63 < len; i += 64) {
00187             lcevc_md5_trans(md5->h, (u32 *)(buf + i));
00188         }
00189         idx = 0;
00190     } else {
00191         i = 0;
00192     }
00193 
00194     if (len - i > 0) {
00195         lcevc_mcpy(md5->msg + idx, buf + i, len - i);
00196     }
00197 }
00198 
00200 
00201 void lcevc_md5_update_16(LCEVC_MD5 *md5, void *buf_t, u32 len) {
00202     u16 *buf;
00203     u32 i, idx, part_len, j;
00204     u8 t[512];
00205 
00206     buf = (u16 *)buf_t;
00207     idx = (u32)((md5->bits[0] >> 3) & 0x3f);
00208 
00209     len = len * 2;
00210     for (j = 0; j < len; j += 2) {
00211         t[j] = (u8)(*(buf));
00212         t[j + 1] = *(buf) >> 8;
00213         buf++;
00214     }
00215 
00216     md5->bits[0] += (len << 3);
00217     if (md5->bits[0] < (len << 3)) {
00218         (md5->bits[1])++;
00219     }
00220 
00221     md5->bits[1] += (len >> 29);
00222     part_len = 64 - idx;
00223 
00224     if (len >= part_len) {
00225         lcevc_mcpy(md5->msg + idx, t, part_len);
00226         lcevc_md5_trans(md5->h, (u32 *)md5->msg);
00227 
00228         for (i = part_len; i + 63 < len; i += 64) {
00229             lcevc_md5_trans(md5->h, (u32 *)(t + i));
00230         }
00231         idx = 0;
00232     } else {
00233         i = 0;
00234     }
00235 
00236     if (len - i > 0) {
00237         lcevc_mcpy(md5->msg + idx, t + i, len - i);
00238     }
00239 }
00240 
00242 
00243 void lcevc_md5_finish(LCEVC_MD5 *md5, u8 digest[16]) {
00244     u8 *pos;
00245     int cnt;
00246 
00247     cnt = (md5->bits[0] >> 3) & 0x3F;
00248     pos = md5->msg + cnt;
00249     *pos++ = 0x80;
00250     cnt = 64 - 1 - cnt;
00251 
00252     if (cnt < 8) {
00253         lcevc_mset(pos, 0, cnt);
00254         lcevc_md5_trans(md5->h, (u32 *)md5->msg);
00255         lcevc_mset(md5->msg, 0, 56);
00256     } else {
00257         lcevc_mset(pos, 0, cnt - 8);
00258     }
00259 
00260     lcevc_mcpy((md5->msg + 14 * sizeof(u32)), &md5->bits[0], sizeof(u32));
00261     lcevc_mcpy((md5->msg + 15 * sizeof(u32)), &md5->bits[1], sizeof(u32));
00262 
00263     lcevc_md5_trans(md5->h, (u32 *)md5->msg);
00264     lcevc_mcpy(digest, md5->h, 16);
00265     lcevc_mset(md5, 0, sizeof(LCEVC_MD5));
00266 }
