00270 // int np; number of planes
00271 // int w[LCEVC_IMGB_MAX_PLANE]; // width in pixels
00272 // int h[LCEVC_IMGB_MAX_PLANE]; // heoght in pixels
00273 // int x[LCEVC_IMGB_MAX_PLANE]; // x position of top left pixel
00274 // int y[LCEVC_IMGB_MAX_PLANE]; // y position of top left pixel
00275 // int s[LCEVC_IMGB_MAX_PLANE]; // stride in bytes
00276 // int e[LCEVC_IMGB_MAX_PLANE]; // elevation in bytes
00277 // void *a[LCEVC_IMGB_MAX_PLANE]; // data address
00278 
00279 /*
00280 p planes
00281 y position
00282 x position
00283 h height
00284 w width
00285 s stride
00286 a address
00287 */
00288 
00289 #include <stdio.h>
00290 
00291 int lcevc_md5_imgb(LCEVC_IMGB *imgb, u8 digest[N_C][16]) {
00292     LCEVC_MD5 md5[N_C];
00293     int i, j;
00294 
00295     for (i = 0; i < imgb->np; i++) {
00296         lcevc_md5_init(&md5[i]);
00297 
00298         // fprintf(stdout, "p %4d - h %4d - w %4d - s %4d \n", i, imgb->h[i], imgb->w[i], imgb->s[i]); fflush(stdout);
00299 
00300         for (j = imgb->y[i]; j < imgb->h[i]; j++) {
00301             lcevc_md5_update(&md5[i], ((u8 *)imgb->a[i]) + j * imgb->s[i] + imgb->x[i], imgb->w[i] * 2);
00302         }
00303 
00304         lcevc_md5_finish(&md5[i], digest[i]);
00305     }
00306 
00307     return LCEVC_OK;
00308 }
